'use strict';
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const escapeHTML = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let KEY=null;
let saved={completed:[],scores:{},notes:{},evidence:{},preChecks:{},exits:{}},storageAvailable=true;
function restorePractice(){ KEY='cs-report-grade9-vr-practice-v1:'+encodeURIComponent(vrSession.id); try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&typeof raw==='object'){saved.completed=Array.isArray(raw.completed)?raw.completed.filter(id=>Number.isInteger(id)&&id>=1&&id<=9):[];for(const prop of ['scores','notes','evidence','preChecks','exits'])if(raw[prop]&&typeof raw[prop]==='object'&&!Array.isArray(raw[prop]))saved[prop]=raw[prop];}}catch(e){storageAvailable=false;} }
let currentLesson=null,currentTab='intro',quizResult=null,filter='Semua',search='';
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));return true;}catch(e){storageAvailable=false;toast('Catatan belum tersimpan. Unduh catatan sebelum menutup halaman.');return false;}}
function storageNote(){return storageAvailable?'Tersimpan untuk akun siswa ini pada browser ini. Unduh catatan untuk cadangan.':'Penyimpanan browser tidak tersedia. Unduh catatan sebelum menutup halaman.';}
function world(){return '<div class="visual" aria-label="Ilustrasi diorama dengan rumah, pohon, dan objek geometris"><div class="visual-grid"></div><div class="visual-top"><span>YOUR WORLD, YOUR IDEAS</span><span>01 / 09</span></div><div class="world" aria-hidden="true"><div class="coordinate-tag">position = 0 1 −3</div><div class="island"></div><div class="tree"></div><div class="tree two"></div><div class="house"></div><div class="orb"></div><div class="floating-cube"></div></div><div class="visual-bottom"><span>Mulai sederhana. Buat jadi milikmu.</span><span class="mini-label">3D · WEB · VR</span></div></div>';}
function updateBookLink(){const a=$('#book-link');if(CONFIG.gradebookUrl){a.href=CONFIG.gradebookUrl;a.target='_self';a.title='Kembali ke buku nilai CS.Report';}else{a.href='#connection';a.removeAttribute('target');}}
function route(){const parts=location.hash.replace(/^#/,'').split('/');currentLesson=null;quizResult=null;const main=$('#main');if(parts[0]==='lesson'||parts[0]==='brief'){const id=Number(parts[1]);currentLesson=LESSONS.find(l=>l.id===id);if(!currentLesson){location.hash='home';return;}currentTab='intro';if(parts[0]==='brief'&&teacherMode()){main.innerHTML=briefPage(currentLesson);bindBrief();}else{main.innerHTML=lessonPage(currentLesson);bindLesson();}}else if(parts[0]==='project'){main.innerHTML=projectPage();bindProject();}else if(parts[0]==='teacher'){if(!teacherMode()){location.hash='#home';route();return;}main.innerHTML=teacherPage();bindTeacher();}else if(parts[0]==='connection'){main.innerHTML=connectionPage();}else{main.innerHTML=homePage();bindHome();}const active=parts[0]||'home';$$('[data-nav]').forEach(a=>{const on=a.dataset.nav===active||(['lesson','brief'].includes(active)&&a.dataset.nav==='home');a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=currentLesson?`${currentLesson.title} — VR Studio`:'VR Studio — Kelas 9';window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
function teacherMode(){return vrTeacherVerified===true&&vrSession?.isTeacherPreview===true;}
function homePage(){const done=saved.completed.length,next=LESSONS.find(l=>!saved.completed.includes(l.id))?.id||1;return '<section class="simple-home"><div class="eyebrow">BSD · Construct a VR World</div><h1>Buat dunia virtualmu.</h1><p>9 pertemuan · 2 JP per pertemuan. Buka tugas → kerjakan di BSD → coba tantangan.</p><a class="btn" href="#lesson/'+next+'">'+(done?'Lanjutkan belajar':'Mulai pertemuan 1')+' →</a><p class="small muted">'+done+' / 9 pertemuan ditandai selesai.</p></section><section><h2>Pilih pertemuan</h2><div class="simple-meetings">'+LESSONS.map(l=>'<a href="#lesson/'+l.id+'"><span>'+l.id+'</span><div><b>'+escapeHTML(l.label)+'</b><small>'+escapeHTML(l.classroom.result)+'</small></div><strong>'+(saved.completed.includes(l.id)?'✓':'→')+'</strong></a>').join('')+'</div></section>';}
function wkaHTML(wka){const refs=wka.sources||[{reference:wka.reference,url:wka.url}];return '<section class="brief-card wka-card"><div class="eyebrow">WKA · Wawasan Kristen Alkitabiah</div><h3>Nilai yang kita praktikkan</h3><p>'+escapeHTML(wka.principle)+'</p><p><b>Tindakan hari ini:</b> '+escapeHTML(wka.practice)+'</p><p class="wka-question">'+escapeHTML(wka.question)+'</p><div class="wka-references">'+refs.map(r=>'<a href="'+escapeHTML(r.url)+'" target="_blank" rel="noopener noreferrer">'+escapeHTML(r.reference)+' ↗</a>').join(' · ')+'</div></section>';}
function courseOverviewHTML(){const b=CONFIG.courseBrief;return '<section class="course-overview" aria-labelledby="course-goal-title"><div class="eyebrow">Gambaran course</div><h2 id="course-goal-title">Apa yang akan kita pelajari?</h2><div class="brief-goal"><span class="mini-label">Tujuan utama</span><p>'+escapeHTML(b.mainGoal)+'</p></div><p class="course-overview-text">'+escapeHTML(b.overview)+'</p><div class="course-stages">'+b.stages.map(([n,t,d])=>'<div><span>Pertemuan '+escapeHTML(n)+'</span><h3>'+escapeHTML(t)+'</h3><p>'+escapeHTML(d)+'</p></div>').join('')+'</div><div class="brief-grid"><section class="brief-card"><h3>Di akhir course, kamu dapat…</h3><ul>'+b.outcomes.map(s=>'<li>'+escapeHTML(s)+'</li>').join('')+'</ul><h3 class="mt">Tugas akhir</h3><p>'+escapeHTML(b.finalTask)+'</p><p class="small muted">Penilaian: diorama & proses 70% · demonstrasi individual 20% · tes konsep 10%.</p><a class="btn secondary" href="#project">Baca brief & rubrik proyek →</a></section>'+wkaHTML(b.wka)+'</div></section>';}
function briefHTML(l){const b=l.brief;return '<div class="lesson-brief" data-brief="'+l.id+'"><div class="brief-goal"><span class="mini-label">Tujuan utama hari ini</span><p>'+escapeHTML(b.mainGoal)+'</p></div><div class="brief-grid"><section class="brief-card"><h3>Materi yang akan kamu pelajari</h3>'+b.material.map(s=>'<p>'+escapeHTML(s)+'</p>').join('')+'<p class="brief-why"><b>Mengapa ini penting?</b> '+escapeHTML(b.why)+'</p></section><section class="brief-card"><h3>Tugasmu hari ini</h3><ol>'+b.tasks.map(s=>'<li>'+escapeHTML(s)+'</li>').join('')+'</ol></section><section class="brief-card"><h3>Berhasil jika kamu dapat…</h3><ul class="brief-success">'+b.success.map(s=>'<li>'+escapeHTML(s)+'</li>').join('')+'</ul><div class="brief-evidence"><b>Bukti yang disiapkan</b><p>'+escapeHTML(l.evidence)+'</p></div></section>'+wkaHTML(b.wka)+'</div><details class="teacher-note brief-script"><summary>Teks pengantar siap dibacakan guru</summary><p>'+escapeHTML(b.teacherScript)+'</p></details></div>';}
function briefPage(l){if(!teacherMode())return lessonPage(l);return '<div class="breadcrumbs"><a href="#home">Pertemuan</a><span>/</span><a href="#lesson/'+l.id+'">'+escapeHTML(l.label)+'</a><span>/</span><span>Brief awal kelas</span></div><article class="brief-page"><header class="brief-page-heading"><div class="eyebrow">Brief awal kelas · Pertemuan '+l.id+' · 80 menit</div><h1>'+escapeHTML(l.title)+'</h1><p>'+escapeHTML(l.subtitle)+'</p><p class="small muted">Gunakan sebagai pengantar 2–3 menit di dalam slot pembuka yang sudah ada.</p></header>'+briefHTML(l)+'<details class="teacher-note"><summary>Lihat agenda 80 menit</summary><ol>'+l.times.map(([t,n])=>'<li>'+escapeHTML(t)+' · '+n+' menit</li>').join('')+'</ol></details><div class="actions brief-navigation">'+(l.id>1?'<a class="btn secondary" href="#brief/'+(l.id-1)+'">← Brief sebelumnya</a>':'')+'<a class="btn" href="#lesson/'+l.id+'">Mulai aktivitas pertemuan '+l.id+' →</a>'+(l.id<9?'<a class="btn secondary" href="#brief/'+(l.id+1)+'">Brief berikutnya →</a>':'')+'<button class="btn secondary" id="print-brief">Cetak brief</button><button class="btn secondary" id="download-brief">Unduh teks pengantar</button></div></article>';}
function briefText(l){const b=l.brief;return 'PERTEMUAN '+l.id+' — '+l.title+'\n\nTUJUAN UTAMA\n'+b.mainGoal+'\n\nRINGKASAN MATERI\n'+b.material.join('\n\n')+'\n\nMENGAPA PENTING\n'+b.why+'\n\nTUGAS SISWA\n'+b.tasks.map((s,i)=>(i+1)+'. '+s).join('\n')+'\n\nKRITERIA KEBERHASILAN\n'+b.success.map(s=>'- '+s).join('\n')+'\n\nBUKTI\n'+l.evidence+'\n\nWKA — '+b.wka.reference+'\n'+b.wka.principle+'\nTindakan: '+b.wka.practice+'\nPertanyaan: '+b.wka.question+'\nSumber: '+b.wka.url+(teacherMode()?'\n\nTEKS PENGANTAR GURU\n'+b.teacherScript:'')+'\n\nAGENDA 80 MENIT\n'+l.times.map(([s,n])=>'- '+s+': '+n+' menit').join('\n');}
function bindBrief(){$('#print-brief').addEventListener('click',()=>window.print());$('#download-brief').addEventListener('click',()=>{download('VR-Studio-Brief-Pertemuan-'+currentLesson.id+'.txt',briefText(currentLesson));toast('Teks pengantar diunduh.');});}

function cards(){const glyphs=['◇','▱','☼','⬡','◎','✎','⌘','✓','✧'];const list=LESSONS.filter(l=>(filter==='Semua'||l.tag===filter)&&`${l.title} ${l.subtitle} ${l.label} ${l.bsd.join(' ')}`.toLocaleLowerCase('id').includes(search.toLocaleLowerCase('id')));return list.length?list.map(l=>`<a class="lesson-card" href="#lesson/${l.id}"><div class="card-art art-${(l.id-1)%4+1}"><span class="num">${String(l.id).padStart(2,'0')}</span><span class="glyph" aria-hidden="true">${glyphs[l.id-1]}</span><span class="tag">${l.tag}</span></div><div class="card-body"><h3>${l.title}</h3><p>${l.subtitle}</p></div><div class="card-bottom"><span>Pertemuan ${l.id} · 80 menit</span><strong>${saved.completed.includes(l.id)?'✓ Ditandai selesai':'Jelajahi →'}</strong></div></a>`).join(''):'<p class="empty">Belum ada materi yang cocok. Coba kata lain atau pilih Semua.</p>';}
function oldBindHome(){$('#search').addEventListener('input',e=>{search=e.target.value;$('#lesson-grid').innerHTML=cards();});$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(btn=>{btn.classList.toggle('active',btn.dataset.filter===filter);btn.setAttribute('aria-pressed',btn.dataset.filter===filter);});$('#lesson-grid').innerHTML=cards();}));}
function bindHome(){}
const tabDefs=[['concept','Contoh & konsep'],['quiz','Kuis latihan']];
function lessonPage(l){currentTab='concept';const c=l.classroom;return '<div class="breadcrumbs"><a href="#home">Pertemuan</a><span>/</span><span>'+l.id+' · '+escapeHTML(l.label)+'</span></div><header class="simple-heading"><div class="eyebrow">Pertemuan '+l.id+' · 80 menit</div><h1>'+escapeHTML(l.title)+'</h1><p>'+escapeHTML(l.brief.mainGoal)+'</p></header><div class="classroom-main"><section class="panel task-card"><div class="eyebrow">01 · Kerjakan</div><h2>Tugas hari ini</h2><p class="bsd-location"><b>Di BSD:</b> '+l.bsd.map(escapeHTML).join(' · ')+'</p><ol class="task-steps">'+c.steps.map(s=>'<li>'+escapeHTML(s)+'</li>').join('')+'</ol><a class="btn" href="'+escapeHTML(CONFIG.bsdUrl)+'" target="_blank" rel="noopener noreferrer">Buka BSD Online ↗</a></section><section class="panel challenge-card"><div class="eyebrow">02 · Coba sendiri</div><h2>Tantangan</h2><p>'+escapeHTML(c.challenge)+'</p><div class="show-result"><b>Tunjukkan hasil:</b> '+escapeHTML(c.result)+'</div></section><section class="panel result-card"><h2>Simpan hasilmu</h2><label class="field-label" for="evidence">Tautan karya / catatan perubahan</label><textarea id="evidence" rows="2" placeholder="Tautan karya atau satu kalimat tentang perubahanmu…">'+escapeHTML(saved.evidence[l.id]||'')+'</textarea><label class="field-label" for="reflection">Apa yang berubah setelah kamu coba?</label><textarea id="reflection" rows="2" placeholder="Satu kalimat cukup.">'+escapeHTML(saved.notes[l.id]||'')+'</textarea><p class="small muted">Tersimpan otomatis pada browser ini. Tunjukkan karya kepada guru.</p><div class="actions"><button id="complete" class="btn '+(saved.completed.includes(l.id)?'done':'')+'">'+(saved.completed.includes(l.id)?'✓ Ditandai selesai':'Tandai latihan selesai')+'</button><button class="btn secondary" id="download-note">Unduh catatan</button></div></section><details class="panel optional-practice"><summary>Perlu bantuan atau mau latihan kuis?</summary><div class="tabs" role="tablist" aria-label="Latihan tambahan">'+tabDefs.map(([id,label])=>'<button type="button" class="tab" role="tab" id="tab-'+id+'" aria-controls="lesson-panel" aria-selected="'+(id===currentTab)+'" tabindex="'+(id===currentTab?0:-1)+'" data-tab="'+id+'">'+label+'</button>').join('')+'</div><section id="lesson-panel" role="tabpanel" aria-labelledby="tab-concept">'+tabContent(l)+'</section></details>'+(teacherMode()?'<details class="panel"><summary>Panduan guru pertemuan ini</summary>'+briefHTML(l)+'<h3>Agenda 80 menit</h3><ol>'+l.times.map(([s,n])=>'<li>'+escapeHTML(s)+' · '+n+' menit</li>').join('')+'</ol><p>'+escapeHTML(l.preparation)+'</p><p>'+escapeHTML(l.support)+'</p><p>'+escapeHTML(l.teacher)+'</p><a class="btn secondary" href="#brief/'+l.id+'">Buka pengantar guru →</a></details>':'')+'<nav class="actions lesson-next">'+(l.id>1?'<a class="btn secondary" href="#lesson/'+(l.id-1)+'">← Sebelumnya</a>':'')+(l.id<9?'<a class="btn secondary" href="#lesson/'+(l.id+1)+'">Pertemuan '+(l.id+1)+' →</a>':'<a class="btn secondary" href="#project">Proyek akhir →</a>')+'</nav></div>';}
function nextTab(){return '';}
function tabContent(l){
 if(currentTab==='concept')return `<div class="eyebrow">Pahami sebelum mengetik</div><h2>Konsep yang kamu perlukan</h2><div class="concepts">${l.concepts.map(([t,p])=>`<div class="concept"><h3>${escapeHTML(t)}</h3><p>${escapeHTML(p)}</p></div>`).join('')}</div>${labHTML(l)}<h3>${l.id>=6?'Panduan berpikir':'Contoh sederhana'}</h3><pre><code>${escapeHTML(l.code)}</code></pre>${l.id<=5?'<p class="small muted">Contoh 1–3 berupa potongan isi scene; contoh 4–5 menunjukkan struktur scene. Muat library A-Frame sesuai BSD. Alamat /resources pada contoh tekstur/model berlaku di BSD; untuk Sandbox, pakai alamat aset yang dapat diakses. Contoh gaze adalah adaptasi sederhana untuk latihan dengan kode awal guru.</p>':''}${nextTab('bsd','Buka panduan latihan')}`;
 if(currentTab==='bsd')return `<div class="eyebrow">Learn & create</div><h2>Praktikkan di BSD</h2><p class="muted">Buka BSD menggunakan akunmu, lalu cari bagian berikut di kelas yang diberikan guru.</p><div class="bsd-items">${l.bsd.map((b,i)=>`<div class="bsd-item"><span>${String(i+1).padStart(2,'0')}</span><b>${escapeHTML(b)}</b></div>`).join('')}</div><p class="small muted">${escapeHTML(l.scope)}</p><h3>Bagian yang dikerjakan hari ini</h3><ul class="summary-list">${l.bsdFocus.map(s=>`<li>${escapeHTML(s)}</li>`).join('')}</ul><div class="evidence"><strong>Target minimum</strong>${escapeHTML(l.minimumTarget)}</div><details class="teacher-note"><summary>Persiapan & bantuan guru</summary><p>${escapeHTML(l.preparation)}</p><p>${escapeHTML(l.support)}</p></details><a class="btn secondary" href="${CONFIG.bsdUrl}" target="_blank" rel="noopener noreferrer">Buka BSD Online ↗</a><h3 class="mt">Tantangan mandiri</h3><p>${l.challenge}</p><div class="evidence"><strong>Bukti yang disiapkan</strong>${l.evidence}</div><label class="field-label" for="evidence">Catatan hasil / tautan karya</label><textarea id="evidence" placeholder="Apa yang kamu buat? Apa yang kamu ubah? Tulis tautan karya jika ada.">${escapeHTML(typeof saved.evidence[l.id]==='string'?saved.evidence[l.id]:'')}</textarea><p class="save-note">${storageNote()}</p>${nextTab('quiz','Cek pemahaman')}`;
 if(currentTab==='quiz')return quizHTML(l);
 return `<div class="eyebrow">Bawa pulang pemahaman</div><h2>Yang perlu kamu ingat</h2><ul class="summary-list">${l.summary.map(s=>`<li>${s}</li>`).join('')}</ul><div class="note-banner">${Number.isFinite(Number(saved.scores[l.id]))&&saved.scores[l.id]!==undefined?`Skor latihan terbaik pada browser ini: <b>${escapeHTML(saved.scores[l.id])}/100</b>. `:''}Kuis dapat diulang untuk belajar. Skornya tidak otomatis dikirim ke BSD atau buku nilai.</div><h3 class="mt">Exit ticket · buktikan pemahaman</h3><label class="field-label" for="exit-ticket">${escapeHTML(l.exitQuestion)}</label><textarea id="exit-ticket" placeholder="Jawab dengan contoh dari karya atau kode yang kamu uji…">${escapeHTML(typeof saved.exits[l.id]==='string'?saved.exits[l.id]:'')}</textarea><details class="teacher-note"><summary>Acuan jawaban · baca setelah mencoba</summary><p>${escapeHTML(l.exitExpected)}</p></details><h3 class="mt">Refleksi belajar</h3><label class="field-label" for="reflection">${l.reflection}</label><textarea id="reflection" placeholder="Tulis pemahaman, kesulitan, atau rencana berikutnya…">${escapeHTML(typeof saved.notes[l.id]==='string'?saved.notes[l.id]:'')}</textarea><p class="save-note">${storageNote()}</p><div class="actions mt"><button class="btn secondary" id="download-note">Unduh catatan pertemuan</button>${l.id<9?`<a class="btn" href="#lesson/${l.id+1}">Pertemuan ${l.id+1} →</a>`:'<a class="btn" href="#project">Lihat rubrik proyek →</a>'}</div>`;
}
function bindLesson(){$$('[data-tab]').forEach(b=>{b.addEventListener('click',()=>switchTab(b.dataset.tab));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let i=tabDefs.findIndex(([id])=>id===currentTab);i=e.key==='Home'?0:e.key==='End'?tabDefs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabDefs.length)%tabDefs.length;switchTab(tabDefs[i][0]);$(`#tab-${currentTab}`).focus();}});});$('#complete').addEventListener('click',()=>{const id=currentLesson.id;const done=saved.completed.includes(id);saved.completed=done?saved.completed.filter(n=>n!==id):[...saved.completed,id];persist();const b=$('#complete');b.classList.toggle('done',!done);b.textContent=done?'Tandai latihan selesai':'✓ Ditandai selesai';toast(done?'Tanda selesai dibatalkan.':'Latihan ditandai selesai pada browser ini.');});bindPanel();}
function switchTab(id){if(!tabDefs.some(([x])=>x===id))return;currentTab=id;quizResult=null;$$('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.tab===id);b.tabIndex=b.dataset.tab===id?0:-1;});$('#lesson-panel').setAttribute('aria-labelledby',`tab-${id}`);$('#lesson-panel').innerHTML=tabContent(currentLesson);bindPanel();}
function bindPanel(){$$('[data-next-tab]').forEach(b=>b.addEventListener('click',()=>{switchTab(b.dataset.nextTab);$(`#tab-${currentTab}`).focus();}));for(const [selector,prop]of [['#reflection','notes'],['#evidence','evidence'],['#exit-ticket','exits']]){const el=$(selector);if(el)el.addEventListener('input',()=>{saved[prop][currentLesson.id]=el.value;persist();});}if($('#download-note'))$('#download-note').addEventListener('click',()=>downloadNote(currentLesson));if($('#quiz-form'))bindQuestionSet('quiz');if($('#pre-form'))bindQuestionSet('pre');bindLab();}
function quizHTML(l){return '<div class="eyebrow">'+(l.id===9?'Latihan tes konsep':'Kuis formatif')+'</div><h2>Sudah paham konsepnya?</h2><p class="muted small">'+l.questions.length+' soal · Bisa diulang · Pembahasan muncul setelah menjawab semua soal. Ini latihan pribadi, bukan nilai resmi.</p>'+(l.id===9?'<div class="note-banner">Kerjakan latihan ini sebelum pertemuan 9. Tes resmi dalam agenda diberikan guru dengan soal berbeda, hanya mencakup materi inti yang diajarkan.</div>':'')+questionSetHTML(l,'quiz')+nextTab('summary','Baca ringkasan');}
function questionSetHTML(l,kind){
 const questions=kind==='pre'?l.openingQuestions:l.questions;
 const baseline=saved.preChecks[l.id];
 const baselineText=kind==='pre'&&baseline&&Number.isFinite(baseline.score)?'<p class="save-note">Hasil pembuka pertama: '+escapeHTML(baseline.score)+'/100. Percobaan ulang tidak mengubah hasil awal ini.</p>':'';
 return baselineText+'<div id="'+kind+'-result" aria-live="polite"></div><form id="'+kind+'-form">'+questions.map(([q,opts],i)=>'<fieldset class="question"><legend>'+(i+1)+'. '+escapeHTML(q)+'</legend>'+opts.map((o,j)=>'<label class="option" data-option="'+i+'-'+j+'"><input type="radio" name="'+kind+'q'+i+'" value="'+j+'"><span>'+escapeHTML(o)+'</span></label>').join('')+'<div id="'+kind+'-feedback-'+i+'"></div></fieldset>').join('')+'<p id="'+kind+'-error" class="error" role="alert"></p><div class="actions"><button class="btn" type="submit">Periksa jawaban →</button><button class="btn secondary" type="button" id="'+kind+'-retry" hidden>Ulangi latihan</button></div></form>';
}
function recordQuestionResult(l,kind,answers){
 const questions=kind==='pre'?l.openingQuestions:l.questions;
 if(answers.length!==questions.length||answers.some((a,i)=>!Number.isInteger(a)||a<0||a>=questions[i][1].length))throw Error('Jawaban belum lengkap atau tidak valid.');
 const correct=questions.reduce((n,q,i)=>n+(answers[i]===q[2]?1:0),0);
 const result={score:Math.round(correct/questions.length*100),correct,total:questions.length,answers:[...answers],submittedAt:new Date().toISOString()};
 if(kind==='pre'){if(!saved.preChecks[l.id])saved.preChecks[l.id]=result;}else saved.scores[l.id]=Math.max(Number(saved.scores[l.id])||0,result.score);
 return result;
}
function bindQuestionSet(kind){
 const form=$('#'+kind+'-form'),l=currentLesson,questions=kind==='pre'?l.openingQuestions:l.questions;
 form.addEventListener('submit',e=>{
  e.preventDefault();const choices=questions.map((_,i)=>form.querySelector('input[name="'+kind+'q'+i+'"]:checked'));
  form.querySelectorAll('fieldset').forEach((f,i)=>{f.style.borderColor=choices[i]?'':'#d9a28d';});
  if(choices.some(x=>!x)){$('#'+kind+'-error').textContent='Jawab semua soal terlebih dahulu. Soal yang belum dijawab ditandai di bawah.';form.querySelector('input[name="'+kind+'q'+choices.findIndex(x=>!x)+'"]').focus();return;}
  $('#'+kind+'-error').textContent='';const result=recordQuestionResult(l,kind,choices.map(c=>Number(c.value)));persist();
  questions.forEach(([q,opts,answer,explanation],i)=>{const selected=Number(choices[i].value);$$('[data-option^="'+i+'-"]',form).forEach(o=>{o.classList.toggle('correct',Number(o.dataset.option.split('-')[1])===answer);o.classList.toggle('wrong',Number(o.dataset.option.split('-')[1])===selected&&selected!==answer);});$('#'+kind+'-feedback-'+i).innerHTML='<div class="feedback"><b>'+(selected===answer?'✓ Tepat.':'Coba pahami lagi.')+'</b> '+escapeHTML(explanation)+'</div>';});
  const initial=kind==='pre'?'<p>Hasil pembuka pertama tetap '+escapeHTML(saved.preChecks[l.id].score)+'/100. Bahas konsep yang belum dikuasai dengan guru.</p>':'<p>Skor latihan terbaik: '+escapeHTML(saved.scores[l.id])+'/100. Baca pembahasan dan jelaskan alasanmu kepada guru.</p>';
  $('#'+kind+'-result').innerHTML='<div class="quiz-result"><strong>'+result.score+'/100</strong><p>'+result.correct+' dari '+result.total+' jawaban tepat pada percobaan ini.</p>'+initial+'</div>';
  $$('input',form).forEach(x=>x.disabled=true);$('button[type=submit]',form).disabled=true;$('#'+kind+'-retry').hidden=false;$('#'+kind+'-result').scrollIntoView({behavior:'smooth',block:'nearest'});
 });
 $('#'+kind+'-retry').addEventListener('click',()=>{switchTab(kind==='pre'?'intro':'quiz');$('#tab-'+currentTab).focus();});
}
function cubeHTML(){return '<div class="cube-wrap" id="cube-wrap"><div class="cube" id="cube">'+['front','back','right','left','top','bottom'].map(f=>`<div class="face ${f}"></div>`).join('')+'</div></div>';}
function labHTML(l){if(['position','scale','light'].includes(l.lab)){const controls=l.lab==='position'?'<label>X · mendatar<input type="range" id="lab-x" min="-2" max="2" value="0" step="0.5"></label><label>Y · tinggi<input type="range" id="lab-y" min="0" max="2" value="1" step="0.5"></label><label>Rotasi Y<input type="range" id="lab-rotation" min="0" max="180" value="0" step="15"></label>':l.lab==='scale'?'<label>Skala seragam<input type="range" id="lab-scale" min="0.3" max="1.5" value="1" step="0.1"></label>':'<label>Intensitas cahaya<input type="range" id="lab-light" min="0.2" max="1" value="0.8" step="0.1"></label><label>Warna objek<select id="lab-color"><option value="#d8ef9b">Hijau daun</option><option value="#e5aa89">Terakota</option><option value="#acd5e5">Biru langit</option></select></label>';return `<div class="lab"><div class="lab-title"><span>COBA SENDIRI</span><span>Simulasi konsep</span></div><div class="lab-stage"><div class="lab-grid" aria-hidden="true"></div>${cubeHTML()}<div class="lab-axis">Y ↑<br>X →</div><output class="lab-state" id="lab-output" aria-live="polite"></output></div><div class="lab-controls">${controls}</div><p class="lab-note">Ilustrasi untuk memahami perubahan ${l.lab==='position'?'posisi dan rotasi':l.lab==='scale'?'ukuran':'tampilan'}. Hasil scene A-Frame yang sebenarnya diuji di BSD.</p></div>`;}
 if(l.lab==='gaze')return '<div class="lab"><div class="lab-title"><span>PEMICU → RESPONS</span><span>Simulasi konsep</span></div><div class="lab-stage"><button type="button" id="gaze-target" class="gaze-target" aria-label="Aktifkan target interaksi" aria-pressed="false">◎</button><p class="gaze-text" id="gaze-text" aria-live="polite">Arahkan pointer atau fokus selama 1 detik. Di ponsel, ketuk.</p></div><p class="lab-note mt">Ini simulasi pemicu dan respons melalui pointer/fokus. Gaze VR yang sebenarnya dipraktikkan melalui BSD.</p></div>';
 return '';}
function bindLab(){if($('#cube')){const update=()=>{const x=Number($('#lab-x')?.value||0),y=Number($('#lab-y')?.value||1),rot=Number($('#lab-rotation')?.value||0),scale=Number($('#lab-scale')?.value||1),light=Number($('#lab-light')?.value||1);$('#cube-wrap').style.transform=`translate(${x*42}px,${(1-y)*45}px) scale(${scale})`;$('#cube').style.transform=`rotateX(-22deg) rotateY(${30+rot}deg)`;$('#cube').style.filter=`brightness(${light})`;if($('#lab-color'))$$('.face').forEach(f=>f.style.background=$('#lab-color').value);$('#lab-output').textContent=$('#lab-scale')?`scale = ${scale.toFixed(1)} ${scale.toFixed(1)} ${scale.toFixed(1)}`:$('#lab-light')?`intensity = ${light.toFixed(1)}`:`position = ${x} ${y} −3 · rotation Y = ${rot}°`;};$$('.lab input,.lab select').forEach(el=>el.addEventListener('input',update));update();}
 if($('#gaze-target')){const target=$('#gaze-target');let timer;const activate=()=>{target.classList.add('is-on');target.setAttribute('aria-pressed','true');target.textContent='✓';$('#gaze-text').textContent='Respons terlihat! Ketuk lagi untuk mengulang.';};const begin=()=>{clearTimeout(timer);timer=setTimeout(()=>{if(target.isConnected)activate();},1000);};const cancel=()=>clearTimeout(timer);target.addEventListener('pointerenter',begin);target.addEventListener('focus',begin);target.addEventListener('pointerleave',cancel);target.addEventListener('blur',cancel);target.addEventListener('click',()=>{cancel();if(target.classList.contains('is-on')){target.classList.remove('is-on');target.setAttribute('aria-pressed','false');target.textContent='◎';$('#gaze-text').textContent='Arahkan pointer atau fokus selama 1 detik. Di ponsel, ketuk.';}else activate();});}}
function download(filename,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function lessonNote(l){return 'PERTEMUAN '+l.id+' — '+l.title+'\nDitandai selesai: '+(saved.completed.includes(l.id)?'Ya':'Belum')+'\nHasil pembuka pertama: '+(saved.preChecks[l.id]?.score===undefined?'Belum':saved.preChecks[l.id].score+'/100')+'\nSkor latihan terbaik: '+(saved.scores[l.id]===undefined?'Belum':saved.scores[l.id]+'/100')+'\nCatatan hasil / tautan karya: '+(saved.evidence[l.id]||'Belum ada.')+'\nExit ticket: '+(saved.exits[l.id]||'Belum ada.')+'\nRefleksi: '+(saved.notes[l.id]||'Belum ada.');}
function downloadNote(l){download('VR-Studio-Pertemuan-'+l.id+'.txt','VR STUDIO — KELAS 9\n'+lessonNote(l)+'\n\nCatatan latihan pribadi pada browser ini; bukan nilai resmi.\n');toast('Catatan diunduh.');}
function projectPage(){return `<div class="breadcrumbs"><a href="#home">Pertemuan</a><span>/</span><span>Proyek akhir</span></div><section class="project-hero"><div><div class="eyebrow">Create · Pertemuan 6–9</div><h1>Diorama milikmu.<br>Keputusan milikmu.</h1><p class="muted">Buat sebuah dunia kecil dengan tema yang jelas. Tunjukkan bahwa kamu bisa menerapkan konsep, menguji hasil, dan menjelaskan keputusanmu.</p><p class="small muted">Cakupan disederhanakan untuk kelas ini. Rubrik berikut adalah rancangan penilaian guru, bukan rubrik resmi BSD.</p></div><div class="project-score"><h3>Komposisi nilai</h3><div class="weight-row"><span>Diorama & proses</span><b>70%</b></div><div class="weight-row"><span>Demonstrasi individual</span><b>20%</b></div><div class="weight-row"><span>Tes konsep</span><b>10%</b></div></div></section><div class="content-grid"><section class="panel"><div class="eyebrow">Versi minimum</div><h2>Yang perlu ada</h2><ul class="checklist"><li>Tema dan pengalaman pengunjung yang jelas.</li><li>Satu objek buatan sendiri dari gabungan bentuk sederhana.</li><li>Tekstur dan pencahayaan yang mendukung tema.</li><li>Satu interaksi yang dapat digunakan pengunjung.</li><li>Catatan sumber dan izin jika memakai aset pihak ketiga.</li><li>Rancangan, pengujian, dan bukti satu revisi.</li></ul><p class="small muted mt">Fitur tambahan dikerjakan setelah versi minimum berjalan. Banyaknya fitur tidak otomatis meningkatkan nilai.</p></section><section class="panel"><div class="eyebrow">Bukti individual</div><h2>Siapkan demonstrasi</h2><ol class="steps"><li>Ceritakan tema dan pengalaman utama.</li><li>Tunjukkan satu fitur yang berfungsi.</li><li>Jelaskan bagian kode yang kamu pahami.</li><li>Jelaskan satu revisi dan alasannya.</li><li>Lakukan modifikasi kecil sesuai arahan guru.</li></ol><p class="small muted">Demonstrasi dikumpulkan pada pertemuan 7–9. Jika proyek berkelompok, setiap siswa tetap diperiksa secara individual.</p><a href="#lesson/6" class="btn secondary">Mulai dari rancangan →</a></section><section class="panel full-width calculator"><div class="eyebrow">Rubrik terbuka</div><h2>Bagaimana karya dinilai?</h2><p class="muted small">Pilih tingkat untuk melihat contoh perhitungan. Kalkulator ini tidak menyimpan atau mengirim nilai resmi.</p><div class="table-wrap"><table class="rubric-table"><thead><tr><th scope="col">Kriteria</th><th scope="col">Maks.</th><th scope="col">Tingkat penguasaan</th><th scope="col">Poin</th></tr></thead><tbody>${RUBRIC.map((r,i)=>`<tr><td><b>${r.name}</b><span class="rubric-caption" id="rubric-desc-${i}">Pilih tingkat untuk membaca deskripsinya.</span></td><td>${r.max}</td><td><select data-rubric="${i}" aria-label="Tingkat ${r.name}"><option value="">Belum dinilai</option><option value="0">0 · Tidak ada bukti</option><option value="1">1 · Perlu bimbingan</option><option value="2">2 · Berkembang</option><option value="3">3 · Baik</option><option value="4">4 · Sangat baik</option></select></td><td id="rubric-points-${i}">—</td></tr>`).join('')}</tbody></table></div><div class="calc-inputs"><label>Demonstrasi individual (0–20)<input id="demo-score" type="number" min="0" max="20" step="0.25" placeholder="Belum dinilai"><span class="save-note">Penjelasan kode 10 · alasan desain 5 · modifikasi 5.</span></label><label>Tes konsep (0–10)<input id="test-score" type="number" min="0" max="10" step="0.25" placeholder="Belum dinilai"><span class="save-note">Gunakan hasil tes yang diberikan guru.</span></label></div><p class="error" id="calc-error" role="alert"></p><div class="calc-total"><div><strong id="calc-label">Lengkapi semua komponen</strong><div class="small" id="calc-detail">Nilai kosong belum dihitung sebagai nol.</div></div><b id="calc-score">— / 100</b></div><p class="save-note">Poin kriteria = tingkat ÷ 4 × poin maksimal. Pilih 0 hanya jika tidak ada bukti.</p><div class="actions mt"><a class="btn" href="${escapeHTML(CONFIG.gradebookUrl)}" target="_blank" rel="noopener noreferrer">Buka buku nilai CS.Report ↗</a><button class="btn secondary" id="download-rubric">Unduh hasil kalkulasi</button><button class="btn secondary" id="print">Cetak brief & rubrik</button></div></section></div>`;}
function bindProject(){let calc=null;function update(){let project=0;let complete=true;$$('[data-rubric]').forEach(s=>{const i=Number(s.dataset.rubric),r=RUBRIC[i];if(s.value===''){complete=false;$(`#rubric-points-${i}`).textContent='—';$(`#rubric-desc-${i}`).textContent='Pilih tingkat untuk membaca deskripsinya.';}else{const level=Number(s.value),points=level/4*r.max;project+=points;$(`#rubric-points-${i}`).textContent=points.toLocaleString('id');$(`#rubric-desc-${i}`).textContent=level===0?'Tidak ada bukti untuk kriteria ini.':r.descriptors[level-1];}});const d=$('#demo-score'),t=$('#test-score');const invalid=[d,t].some(el=>el.value!==''&&(!Number.isFinite(Number(el.value))||Number(el.value)<0||Number(el.value)>Number(el.max)||!el.checkValidity()));$('#calc-error').textContent=invalid?'Periksa nilai: demonstrasi 0–20 dan tes 0–10, dengan kelipatan 0,25.':'';complete=complete&&d.value!==''&&t.value!==''&&!invalid;const sum=project+Number(d.value)+Number(t.value);$('#calc-label').textContent=complete?'Contoh nilai akhir':'Lengkapi semua komponen';$('#calc-detail').textContent=`Proyek ${project.toLocaleString('id')}/70 · ${complete?'Semua komponen telah diisi.':'Nilai kosong belum dihitung sebagai nol.'}`;$('#calc-score').textContent=complete?`${sum.toLocaleString('id')} / 100`:'— / 100';calc=complete?{project,demo:Number(d.value),test:Number(t.value),total:sum,levels:$$('[data-rubric]').map(s=>Number(s.value))}:null;}
 $$('[data-rubric],#demo-score,#test-score').forEach(el=>el.addEventListener('input',update));$('#print').addEventListener('click',()=>window.print());$('#download-rubric').addEventListener('click',()=>{if(!calc){toast('Lengkapi semua komponen dengan nilai yang valid.');return;}download('VR-Studio-Kalkulasi-Rubrik.txt',`VR STUDIO — KALKULASI RUBRIK\nContoh perhitungan; bukan catatan nilai resmi.\n\n${RUBRIC.map((r,i)=>`${r.name}: tingkat ${calc.levels[i]}, ${calc.levels[i]/4*r.max}/${r.max}`).join('\n')}\nProyek: ${calc.project}/70\nDemonstrasi individual: ${calc.demo}/20\nTes konsep: ${calc.test}/10\nTotal: ${calc.total}/100\n`);toast('Hasil kalkulasi diunduh.');});}
function teacherPage(){if(!teacherMode())return homePage();return `<div class="eyebrow">Ruang fasilitasi</div><h1 style="font-size:42px">Arah yang jelas.<br>Bukti belajar yang nyata.</h1><p class="muted">Panduan ${escapeHTML(CONFIG.teacher)} untuk memimpin 9 pertemuan. BSD menyediakan latihan; percakapan, modifikasi, dan revisi membantu memeriksa penguasaan.</p><div class="note-banner"><b>Asumsi waktu:</b> 1 JP = 40 menit, sehingga 9 × 2 JP = 12 jam. Overview BSD mengalokasikan 25 jam untuk seluruh course. Rencana ini memilih materi inti; sesuaikan tempo dengan kesiapan HTML dan JavaScript siswa.</div><section class="panel class-brief-guide"><div class="eyebrow">Siap membuka kelas</div><h2>Tujuan, materi, tugas, dan WKA</h2><p>Siswa melihat tugas singkat, tantangan, dan hasil. Panduan lengkap, agenda, WKA, dan teks pengantar tersedia di mode guru. Gunakan pengantar untuk penjelasan lisan singkat.</p><p class="small muted">Gunakan 2–3 menit dari slot pembuka yang sudah dijadwalkan. WKA dirumuskan sebagai penerapan prinsip Alkitab pada kegiatan belajar; sumber ayat tersedia pada setiap brief.</p><div class="actions"><a class="btn" href="#brief/1">Tampilkan brief pertemuan 1 →</a><button class="btn secondary" id="download-all-briefs">Unduh semua teks pengantar</button></div></section><section class="panel mt"><h2>Peta pertemuan & bukti</h2><div class="table-wrap"><table class="schedule"><thead><tr><th>Pertemuan</th><th>Fokus BSD & batas aktivitas</th><th>Bukti belajar</th></tr></thead><tbody>${LESSONS.map(l=>`<tr><td><a href="#lesson/${l.id}">${l.id}. ${l.label}</a><small>2 JP · 80 menit</small><a class="brief-table-link" href="#brief/${l.id}">Brief awal kelas →</a></td><td>${l.bsd.map(escapeHTML).join('<br>')}<small>${l.bsdFocus.map(escapeHTML).join('<br>')}</small><details><summary>Persiapan & bantuan</summary><p>${escapeHTML(l.preparation)}</p><p>${escapeHTML(l.support)}</p></details></td><td>${l.evidence}</td></tr>`).join('')}</tbody></table></div></section><div class="content-grid mt"><section class="panel"><h2>Formatif yang ringan</h2><p class="small muted">Tanpa diagnostik atau kuis pembuka wajib. Gunakan pemeriksaan karya, satu pertanyaan lisan, dan tantangan modifikasi. Bank 34 soal sesudah belajar tersedia sebagai latihan pilihan; 10 soal pertemuan 9 adalah persiapan tes. Soal disusun sebagai pendamping BSD, bukan salinan bank soal resmi.</p><ul class="summary-list"><li><b>Perlu bimbingan:</b> masih kesulitan menjelaskan atau menerapkan konsep.</li><li><b>Berkembang:</b> dapat menerapkan dengan pertanyaan pemandu.</li><li><b>Mandiri:</b> dapat menerapkan dan menjelaskan alasannya.</li></ul><p class="small muted">Ambil bukti pada akhir proyek atau kelompok materi. Gunakan hasil untuk bantuan dan pengayaan. Status “Passed” BSD dan kuis latihan tidak menggantikan percakapan pemahaman.</p></section><section class="panel"><h2>Pertanyaan saat berkeliling</h2><ul class="summary-list"><li>Apa yang kamu harapkan, dan apa yang terjadi?</li><li>Bagian kode mana yang mengatur perubahan itu?</li><li>Apa dugaanmu? Satu perubahan apa yang akan diuji?</li><li>Mengapa pilihan visual ini mendukung temamu?</li><li>Apa yang kamu perbaiki setelah teman mencoba?</li></ul></section></div><section class="project-banner"><div><h3>Penilaian akhir, bukti individual.</h3><p>70% diorama & proses · 20% demonstrasi individual · 10% tes konsep. Mulai demonstrasi pada pertemuan 7. Slot total 7–9 adalah 80 menit, sekitar 26 siswa jika 3 menit per siswa. Untuk kelas lebih besar, kumpulkan rekaman penjelasan sebelumnya lalu lakukan verifikasi/modifikasi langsung singkat. Kuis terbuka pertemuan 9 dikerjakan untuk persiapan sebelum tes resmi.</p></div><a class="btn green" href="#project">Buka rubrik →</a></section><section class="panel mt"><h2>Catatan belajar & buku nilai</h2><p class="muted small">Catatan dan skor latihan di website ini dipisahkan menurut identitas siswa pada browser yang sedang digunakan. Website tidak menyinkronkan daftar siswa, hasil kuis, atau nilai dengan BSD maupun buku nilai. Gunakan hasil demonstrasi dan rubrik untuk pencatatan resmi. Buku nilai tersedia di <b>CS.Report</b>; pilih <b>LOGIN GURU</b> pada website tersebut untuk masuk.</p><div class="actions"><a class="btn" href="${CONFIG.gradebookUrl?escapeHTML(CONFIG.gradebookUrl):'#connection'}" ${CONFIG.gradebookUrl?'target="_blank" rel="noopener noreferrer"':''}>Buka buku nilai ↗</a><button class="btn secondary" id="export-all">Unduh semua catatan latihan</button><button class="btn secondary" id="reset-practice">Atur ulang catatan browser</button></div><div id="reset-confirm" hidden class="note-banner">Hapus semua catatan latihan, skor latihan, dan tanda selesai pada browser ini? <div class="actions mt"><button id="confirm-reset" class="btn">Ya, hapus catatan latihan</button><button id="cancel-reset" class="btn secondary">Batal</button></div></div></section><p class="scope-note">Dasar course: <a href="https://app.bsd.education/resources/CORE%20CONTENT/TechNovators/Construct%20a%20VR%20world/General%20Resources/Construct%20a%20VR%20World%20-%20Overview.pdf" target="_blank" rel="noopener noreferrer">Overview BSD Construct a VR World</a>. Materi pengantar dan kuis website ini disusun sebagai pendamping kelas.</p>`;}
function bindTeacher(){$('#download-all-briefs').addEventListener('click',()=>{download('VR-Studio-Semua-Brief-Kelas.txt',LESSONS.map(briefText).join('\n\n━━━━━━━━━━━━━━━━━━━━\n\n'));toast('Semua teks pengantar diunduh.');});$('#export-all').addEventListener('click',()=>{download('VR-Studio-Semua-Catatan.txt',LESSONS.map(lessonNote).join('\n\n')+'\n\nCatatan latihan pribadi; bukan nilai resmi.');toast('Semua catatan latihan diunduh.');});$('#reset-practice').addEventListener('click',()=>{$('#reset-confirm').hidden=false;$('#cancel-reset').focus();});$('#cancel-reset').addEventListener('click',()=>{$('#reset-confirm').hidden=true;$('#reset-practice').focus();});$('#confirm-reset').addEventListener('click',()=>{saved={completed:[],scores:{},notes:{},evidence:{},preChecks:{},exits:{}};persist();$('#reset-confirm').hidden=true;$('#reset-practice').focus();toast('Catatan latihan pada browser ini diatur ulang.');});}
function connectionPage(){return `<div class="breadcrumbs"><a href="#home">Beranda</a><span>/</span><span>Buku nilai</span></div><section class="panel" style="max-width:750px"><div class="eyebrow">CS.Report · Pencatatan nilai</div><h1 style="font-size:36px">Buku nilai kelas 9</h1><p>Gunakan CS.Report untuk membuka buku nilai Anda. Pada halaman CS.Report, pilih <b>LOGIN GURU</b> untuk masuk sebagai guru. Siswa dapat menggunakan pencarian dan mengikuti akses siswa yang tersedia di sana.</p><p class="muted">Nilai resmi menggunakan rubrik proyek, demonstrasi individual, dan tes konsep. Kuis latihan di VR Studio tidak otomatis dikirim ke buku nilai.</p><div class="actions"><a class="btn" href="${escapeHTML(CONFIG.gradebookUrl)}" target="_blank" rel="noopener noreferrer">Buka CS.Report ↗</a><a class="btn secondary" href="#project">Lihat rubrik & kalkulator</a></div></section>`;}
$('.skip').addEventListener('click',e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView({behavior:'smooth',block:'start'});});
